// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":395,"question":"هل يصح قول القائل: إنَّ عمل السلف بخلاف الحديث يؤكد أنَّ الحديث ليس على ظاهره، إذا كان كذلك في حال اتِّفاق السلف على العمل بخلاف ظاهر الحديث، فما هو الحال عند اختلافهم، كما هو الحال في حجّة التمتع من (......) عمران بن حصين، كقوله: \"تمتعنا مع النبي ﷺ، وتمتعنا مع أبي بكر، ثم جاءنا رجلٌ وقال برأيه ما شاء\" يقصد: عمر، وضِّح لنا ذلك.","title":"هل يجوز العمل بخلاف ظاهر الحديث؟","answer":"الجواب: هذا تسويغٌ غير صحيحٍ، ما هناك إجماعٌ من السلف ولا اتِّفاقٌ من السلف على خلاف الحديث الصحيح، ومَن زعم فعليه الدليل.\nالسلف بحمد الله قد حماهم الله أن يُخالفوا سنة النبي ﷺ، يقول: لا تزال طائفةٌ من أمتي على الحقِّ منصورة، لا يضرُّهم مَن خذلهم، ولا مَن خالفهم حتى يأتي أمر الله، وعمر  والصديق حين دعوا إلى الحج المفرد اجتهادًا منهما، ولم يُجمع السلفُ على وفاقهما، ولا على خلافهما، فهذه مسألةٌ اجتهادية من الصديق، ومن عمر، ومن عثمان في إفراد الحج، قالوا: ليكثر زوار البيت، هذا للعمرة، وهذا للحج؛ اجتهادًا منهما، ولم يُنكرا السنة.\nفلما جاء الصبي بن معبد التّغلبي إلى عمر وقال: يا أمير المؤمنين، أحرمتُ بحجٍّ وعمرةٍ، فقال لي جماعةٌ: كذا وكذا، قال: هُديت لسنة نبيك عليه الصلاة والسلام، وهكذا لما سمع عليٌّ  عثمان بالدعوة إلى إفراد الحج أحرم بالحج والعمرة وقال: \"لا أدعهما وقد سمعتُ الرسول ﷺ أحرم بهما\".\nفالحاصل أن السلف لم يُجمعوا على خلاف السنة، ولن يُجمعوا على خلاف السنة أبدًا، وهذه القضية التي هي قضية عمر ليس فيها إجماعٌ، وإنما هذا اجتهادٌ من الصديق وعمر وعثمان في إفراد الحج  ولهم اجتهادهم، والله يُعطيهم أجرهم ، ولكن ما فعله النبيُّ ﷺ هو أفضل مما فعله الصديقُ وعمر وعثمان، ومن الإحرام إلى الإحرام بعمرةٍ ثم بالحج لما أمر أصحابه بذلك، وبالقِران بين الحج والعمرة إذا كان معه الهدي عليه الصلاة والسلام.\nفالحاصل أنَّ الذي فعله وأمر به هو الأفضل، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/4782/هل-يجوز-العمل-بخلاف-ظاهر-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0452.mp3","categories":["الحديث وعلومه"]},{"id":994,"question":"يقول: وهذا الرجل كذلك يُشكك الناسَ في حديث رسول الله ﷺ، حيث يقول: أنا لا أشك في البخاري ومسلم، ولكن الذين أخذوا عنهم ربما أنَّهم كذبوا على الرسول، أو غيَّروا في معنى الحديث، أو نحو هذا، ما هو ردُّ فضيلتكم على هذا الشخص وأمثاله؟ جزاكم الله خيرًا.","title":"ما الرد على من يطعن في أئمة الحديث؟","answer":"الجواب: وهكذا السنة محفوظة، قد قيَّض الله لها نُقَّادها، وبيَّنوا ما وقع فيها من أخطاء وكذبٍ وغلطٍ، والله قيَّض لها أئمةً من الصحابة ومَن بعدهم حتى حفظوها، يقول الله جلَّ وعلا: وَالنَّجْمِ إِذَا هَوَى  ۝  مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى  ۝  وَمَا يَنْطِقُ عَنِ الْهَوَى [النجم:1- 3]، فحفظ الكتاب حفظٌ للسنة، فحفظ السنة من حفظ الكتاب؛ لأنها تفسير القرآن، وبيان معناه، وما أشكل منه، فالذي حفظ القرآن حفظ السنة، فحفظه للقرآن لقوله جلَّ وعلا: وَإِنَّا لَهُ لَحَافِظُونَ [الحجر:9] حفظٌ للسنة، ولهذا وصلت إلينا من طريق البخاري ومسلم وغيرهم من أئمة العلم محفوظةً سليمةً، من طريق الثِّقات عن أصحاب النبي ﷺ، عن النبي عليه الصلاة والسلام، وقيَّض الله لها أئمةً في عهد الصحابة والتابعين وأتباع التابعين وبعدهم بيَّنوا الصحيح من السَّقيم، والضعيف والمكذوب والموضوع، وبيَّنوا الرجال: ثقاتهم، وسيئ الحفظ منهم، والكذَّاب، ومَن به غفلة، إلى غير ذلك، فأبانوا كلَّ ما يتعلق بصحة الحديث، وحفظه، وبيان الحديث الضعيف، والموضوع، فلم تبق بحمد الله شُبهةٌ لمشبه.","link":"https://binbaz.org.sa/fatwas/21042/ما-الرد-على-من-يطعن-في-اىمة-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0838ما ردكم بمن يقول أن من أخذ عن البخاري ومسلم وبقية السنن غيروا الأحاديث أو كذبوا على الرسول؟.mp3","categories":["الحديث وعلومه"]},{"id":1040,"question":"ما حكم مَن أنكر أخبار الآحاد من السنة وإن كانت صحيحةً، بل ويرد ما في \"الصحيحين\" بحجّة عدم مُوافقتها للعقل؟","title":"ما حكم مَن أنكر أخبار الآحاد في السُّنة؟","answer":"الجواب: يُعتبر ضالًّا مُضلًّا، يُعتبر مُخطئًا، غلطان، ولا يُتابع، ولا يُؤخذ بقوله، بل هو غلطان، وهو على خطرٍ عظيمٍ من هذا القول، فأهل السنة والجماعة أجمعوا على قبول خبر الآحاد، والاحتجاج به، وممن حكى ذلك الخطيبُ البغدادي، وابن عبدالبر رحمهما الله، وغيرهما، كلاهما ذكر إجماع أهل العلم على قبول خبر الآحاد إذا صحَّت الأسانيد، وهكذا قال أحمد وغيره من الأئمة، كلهم أجمعوا على قبول خبر الآحاد إذا صحَّت بها الأسانيد عن رسول الله عليه الصلاة والسلام، فمَن زعم إنكارها، أو طعن فيها، أو قال: لا يُحتجّ بها في العقائد؛ فقد غلط غلطًا عظيمًا، فهي حُجَّة في العقائد وغير العقائد.","link":"https://binbaz.org.sa/fatwas/21085/ما-حكم-من-انكر-اخبار-الاحاد-في-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0881ما حكم من أنكر أخبار الآحاد من السنة وإن كانت صحيحة؟ ابن باز فتاوى المحاضرات.mp3","categories":["الحديث وعلومه"]},{"id":1041,"question":"ما رأيكم في \"سلسلة الأحاديث الضعيفة\" للشيخ الألباني؟","title":"ما الرأي في سلسلة \"الضعيفة\" للشيخ الألباني؟","answer":"الجواب: كتب الألباني كتب جيدة ومفيدة، وهو من إخواننا الطيبين، ومن أصحاب العقيدة الطيبة، فـ\"السلسلة الصحيحة\" و\"الضعيفة\" كلها كتب مفيدة، ولكن لا تخلو من بعض الانتقاد في بعضها، كلٌّ يُؤخَذ من قوله ويُترك، فليس بمعصومٍ، لا هو ولا غيره من أهل العلم، قد يقع في \"الضَّعيفة\" ما لا يُتابَع عليه، ويقع في \"الصحيحة\" ما لا يُتابع عليه، لكن هذا إنما ينتبه له أهلُ العلم والبصيرة الذين يعرفون الأحاديث، ويعرفون طرقها ورجالها، وهو مجتهدٌ، والغالب عليه والحمد لله التوفيق، ولكن ليس معناه أنَّ كل ما ذكر صحيحٌ، وأنه لا يغلط، لا، قد يقع، قد وقع له بعض الأغلاط، وكلٌّ منا يغلط، وكل أحدٍ يغلط، حتى العلماء الكبار قبله، فهو ليس معناه أنه مُسلَّمٌ له كلّ ما يقول، بل قد تقع بعض الأغلاط، فطالب العلم ينتبه ويُراجعه، ويعتني، وهو من خيرة أهل العلم في زماننا هذا، وفَّقه الله وزاده خيرًا.","link":"https://binbaz.org.sa/fatwas/21084/ما-الراي-في-سلسلة-الضعيفة-للشيخ-الالباني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0880ما رأيكم في سلسلة الأحاديث الضعيفة للشيخ ناصر الدين الألباني؟ ابن باز فتاوى المحاضرات.mp3","categories":["الحديث وعلومه"]},{"id":1042,"question":"هل في \"الصحيحين\" أحاديث ضعيفة؟ وكيف نرد على مَن زعم أنَّ فيهما أحاديث ضعيفة؟","title":"ما الرد على أن بالصحيحين أحاديث ضعيفة؟","answer":"الجواب: الصواب: ليس فيهما أحاديث ضعيفة، كلها مقبولة عند أهل العلم، كلها صحيحة مقبولة، مُتلقَّاة بالقبول عند أهل العلم، والبخاري في القمة، ثم يليه مسلم، سوى حديثٍ واحدٍ أعلَّه بعضُ أهل العلم، وهو حديث: أنَّ الله خلق التربةَ يوم السبت... إلى آخره، حديث أبي هريرة، رواه مسلم، هذا رواه مسلم وجعل فيه أيام الخلق سبعة، وهو وهمٌ من بعض الرواة، أصل الحديث صحيحٌ، لكن وهم بعضُ الرواة فجعله من كلام النبي ﷺ، وهو من كلام كعب الأحبار، ليس من كلام النبي، فغلط فيه بعضُ الرواة، ولم ينتبه لذلك مسلم رحمه الله، ورواه على ما بلغه شيخه. ولكن بيَّن البخاري وجماعةٌ علَّته؛ لأنَّ فيه زيادةَ يوم، والله خلق السَّماوات والأرض في ستة أيام، لا في سبعة، فهذا وهمٌ من بعض الرواة فيما رواه ورفعه للنبي ﷺ، وإنما هو من أغلاط كعب الأحبار في الأيام التي تمَّ فيها الخلقُ، وهي ستة لا سبعة.\nأما وجود بعض الكلمات التي قد يَهِم فيها بعضهم، هذا قد يقع في \"الصحيحين\" وغير \"الصحيحين\"، ولكن جملة الأحاديث كلها مُتلقاة بالقبول، وكلها مُعتمدة وصحيحة.","link":"https://binbaz.org.sa/fatwas/21083/ما-الرد-على-ان-بالصحيحين-احاديث-ضعيفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0879كيف نرد على من يقول أن في الصحيحين أحاديث ضعيفة؟ ابن باز فتاوى المحاضرات.mp3","categories":["الحديث وعلومه"]},{"id":1282,"question":"قول بعض أهل العلم أنه يُعمل بالحديث الضَّعيف في فضائل الأعمال، نرجو التفصيل في هذه المسألة؟","title":"حكم العمل بالحديث الضعيف في الفضائل؟","answer":"الجواب:\nهذا قول الأكثرين، العمل بالضعيف الذي لم تصل درجته إلى الوضع أو الضعف الشديد. ومعنى \"الضعيف\" هو الحسن عند الترمذي، الذي له شواهد، يعني: رواه أناسٌ فيهم ضعف، فيهم سُوء حفظٍ، ولكن له شواهد، هذا الضَّعيف.  أما الموضوع والمكذوب أو المتَّهم صاحب الكذب: فهذا لا يُذكر حتى في الترغيب والترهيب.  لكن إذا كانت له شواهد أو الراوي له فيه بعض الضعف اليسير من سُوء الحفظ فهذا يُذكر في الترغيب والترهيب، وتركه أوْلى، فالناس في حاجةٍ إلى الصحيح، مثلما قال مسلمٌ رحمه الله: \"الناس في حاجةٍ إلى الصحيح\"، يكفي في الترغيب والترهيب الأحاديث الصحيحة والآيات، والحمد لله، فترك الضعيف في الترغيب والترهيب أوْلى، ولو أجازه الجمهور فتركه أوْلى، يُكتفي بالصحيح أحسن له إذا تيسر، لكن لو ذكر الضعيفَ كما ذكره الجمهور -الذي ليس بموضوعٍ، ولا مُقارب للموضوع- فلا حرج.","link":"https://binbaz.org.sa/fatwas/21323/حكم-العمل-بالحديث-الضعيف-في-الفضاىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1066هل يجوز العمل بالحديث الضعيف في فضائل الأعمال؟ ابن باز.mp3","categories":["الحديث وعلومه"]},{"id":1362,"question":"ما هو سبب قلة حديث أبي بكر الصديق؟","title":"ما سبب قلة أحاديث أبي بكر رضي الله عنه؟","answer":"الجواب:\nما عاش بعد النبي ﷺ إلا سنتين وأشهر، ما طالت مدته، مدة خلافته سنتان وأشهر.","link":"https://binbaz.org.sa/fatwas/21455/ما-سبب-قلة-احاديث-ابي-بكر-رضي-الله-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سبب قلة أحاديث أبي بكر الصديق رضي الله عنه.mp3","categories":["الحديث وعلومه"]},{"id":1495,"question":"بالنسبة لتحقيقات الشيخ شعيب الأرناؤوط وتخريجاته؟","title":"ما درجة تحقيقات الشيخ شعيب الأرناؤوط؟","answer":"الجواب:\nفيها بعض الملاحظات، كتب بعضُ الإخوان ملاحظات يمكن بعد أن يُكْمِل تُطبع.","link":"https://binbaz.org.sa/fatwas/21593/ما-درجة-تحقيقات-الشيخ-شعيب-الارناووط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في تحقيقات الشيخ شعيب الأرناؤوط.mp3","categories":["الحديث وعلومه"]},{"id":2519,"question":"الأحاديث التي انتقدها الدارقطني على البخاري ومسلم صحيحة؟","title":"ما حكم انتقادات الدارقطني على الصحيحين؟","answer":"الجواب: بعض القول فيها قول البخاري، الغالب أن القول فيها قول البخاري.","link":"https://binbaz.org.sa/fatwas/22649/ما-حكم-انتقادات-الدارقطني-على-الصحيحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأحاديث التي انتقدها الدارقطني على البخاري ومسلم صحيحة.mp3","categories":["الحديث وعلومه"]},{"id":2602,"question":"قد يكون الحديث ضعيف السند لكن معناه صحيح، فهل يُعمل به؟","title":"هل يُعمل بالحديث الضعيف لو صحَّ معناه؟","answer":"الجواب: يُعمل بالأصل، الأصل ما دل عليه القرآن والأحاديث الصحيحة.\nس: الشيخ ناصر الألباني حفظه الله يقول إن الحديث الضعيف مبني على الظن، ولهذا لا يرى العمل به؛ لأنه مبني على الظن، وأن الظن أكذب الحديث؟\nالشيخ: لا لا، الأحاديث الضعيفة تُستعمل في الترغيب والترهيب، ويُستعمل في التي ثبت أصلُها.\nس: رد على هذا قال إن الأحاديث الصحيحة مليئة بأحاديث الترغيب والترهيب، فلماذا يُستغنى عنها؟\nالشيخ: لا بأس، ذِكْرُها من باب الترغيب والترهيب، رُوي عن النبي ﷺ، مثل ما قال العلماء، روي يذكر مِنْ غير جَزْم.","link":"https://binbaz.org.sa/fatwas/22736/هل-يعمل-بالحديث-الضعيف-لو-صح-معناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُعمل بالحديث ضعيف السند صحيح المعنى.mp3","categories":["الحديث وعلومه"]},{"id":2653,"question":"الأحاديث التي في الرغائب يجوز العمل بها حتى وإن كانت ضعيفة؟","title":"ما حكم العمل بالحديث الضعيف في الرغائب؟","answer":"الجواب: إذا كان اثنان فأكثر يَشُدُّ بعضها، تكون من باب الحَسَن لغيره، أما إذا كان واحد ضعيف وحده ما يُحتج به، لكن يُذكر في الفضائل فقط للتشجيع على الخير.","link":"https://binbaz.org.sa/fatwas/22789/ما-حكم-العمل-بالحديث-الضعيف-في-الرغاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز العمل بالأحاديث الضعيفة في الرغائب.mp3","categories":["الحديث وعلومه"]},{"id":2657,"question":"بالنسبة لما رواه البخاري مُعَلَّقًا هل يُجزم بصحته؟","title":"هل يُجْزَم بصحة ما رواه البخاري مُعَلّقًا؟","answer":"الجواب: يختلف:  إذا كان رواه جازمًا فهو صحيح. وإذا كان رواه بالتمريض؛ يُذكر ويُروى، ضعيف وصحيح.","link":"https://binbaz.org.sa/fatwas/22793/هل-يجزم-بصحة-ما-رواه-البخاري-معلقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة ما رواه البخاري معلقا.mp3","categories":["الحديث وعلومه"]},{"id":2905,"question":"حكم أحمد شاكر على بعض الأحاديث؟","title":"ما درجة حكم أحمد شاكر على الأحاديث؟","answer":"الجواب: عنده بعض التساهل، يعفو عنا وعنه، في التحسين والتصحيح، صحح حديث ابن لهيعة وجماعة من الضعفاء.","link":"https://binbaz.org.sa/fatwas/23061/ما-درجة-حكم-احمد-شاكر-على-الاحاديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أحمد شاكر على بعض الأحاديث.mp3","categories":["الحديث وعلومه"]},{"id":3047,"question":"وجَرْح الرواة؟","title":"حكم جَرْح الرُّواة","answer":"الجواب: جَرْح الرواة من التعريف، ومن النصيحة، يدخل في الأمرين، يدخل في النصيحة ويدخل في التعريف، جرح الرواة: هذا ضعيف، هذا وضّاع، هذا مبتدع، هذا كثير الغلط، هذا من النصيحة لله ولعباده، ومن التعريف أيضًا، يدخل في التعريف وهو من النصيحة.\nس: هل تُذكر حسناتُهم؟\nالشيخ: لا ما لزوم، المقصود بيان العيب للحذر منه، ما هو المقصود بيان الحسنات، المقصود بيان العيوب التي يُحْذَر منها.","link":"https://binbaz.org.sa/fatwas/23207/حكم-جرح-الرواة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم جرح الرواة.mp3","categories":["الآداب والأخلاق","الحديث وعلومه"]},{"id":3250,"question":"تصحيح الترمذي يُؤخذ به؟","title":"ما حكم تصحيح الترمذي للحديث؟","answer":"الجواب: نعم في الأغلب، وقد يغلط، لكن في الأغلب جيد تحسينه وتصحيحه في الأغلب.\nس: وإذا قال: حَسَن، فقط؟\nج: هذا اصطلاح له، الحسن: ما روي عن غير وجه، ولم يكن في رواته متهم بالكذب ولم يكن شاذًّا يسميه \"حَسَن\"، وقد يُتبعه بغريب، وقد يقول: حسن صحيح غريب، اصطلاح له رحمه الله، الترمذي له اصطلاح، لكن ينبغي مع هذا كله أن يُراجع إسناده، ولا يغتر به، تحسينه وتضعيفه بعض الأحيان قد يتساهل، بعض الأحيان، رحمه الله، عفا الله عنا وعنه.","link":"https://binbaz.org.sa/fatwas/23414/ما-حكم-تصحيح-الترمذي-للحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يؤخذ بتصحيح الترمذي.mp3","categories":["الحديث وعلومه"]},{"id":3291,"question":"قول علقمة: سمعت عمر بن الخطاب يخطب على المنبر، أليس غريبًا أن يكون هو الذي رواه وحده وسمعه على المنبر؟","title":"ما أصح روايات حديث \"الأعمال بالنيات\"؟","answer":"الجواب: هو ما ثبت إلا من طريقه من الطرق الصحيحة هذا اللفظ إلا من طريق عمر.","link":"https://binbaz.org.sa/fatwas/23456/ما-اصح-روايات-حديث-الاعمال-بالنيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إنما الأعمال بالنيات.. مروي عن علقمة فهل يكون هو الذي رواه وحده وسمعه.mp3","categories":["الحديث وعلومه"]},{"id":3335,"question":"المعروف أن مسلم بن الحجاج يفرق بينهما: وجه التفريق بين حدثنا، وأخبرنا؟","title":"ما الفرقبين حدثنا وأخبرنا في الرواية؟","answer":"الجواب: بعض الفقهاء المتأخرين، وإلا المتقدمين ما يفرقون بينهما، بعض المتأخرين يخص أخبرنا، وأنبأنا، بالإجازة.","link":"https://binbaz.org.sa/fatwas/23501/ما-الفرق-بين-حدثنا-واخبرنا-في-الرواية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجه التفريق بين حدثنا، وأخبرنا.mp3","categories":["الحديث وعلومه"]},{"id":3338,"question":"الكتابة والمُناولة: شيء آخر، أم شيء واحد؟","title":"الفرق بين الكتابة والمُناولة في الحديث","answer":"الجواب: لا كتابه أبلغ، إذا كتب له أبلغ، مثلما كتب لأبي هشام، كتب لقيصر، وغيره.. المناولة إذا ناوله إياها لا بأس، قال: اروه عني، أو قال هذا روايتي، يعني: شيء يبيّن له أنه روى هذه الأحاديث.","link":"https://binbaz.org.sa/fatwas/23504/الفرق-بين-الكتابة-والمناولة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الكتابة والمناولة في الحديث.mp3","categories":["الحديث وعلومه"]},{"id":3342,"question":"بعض رواة الحديث كابن عُلَيَّة يقول: من سمّاني ابن علية فقد اغتابني؟","title":"هل مِن الغِيبة ذِكْرُ بعض الرواة بما يَكرهون؟","answer":"الجواب: ولو إذا كان ما يُعْرَف إلا بذلك لا حرج، مثلما يقال الأعور، والأعمى؛ للتعريف، ما هو بقَصد الغيبة، ولو قال، هذا من باب التعريف، ولهذا جرّح العلماء الرواة الضعفاء، والمجروحين، إذا كان في جَرْحه مصلحة، مثلما ضبطه بعضهم في البيتين: لأن الغيبة يحتاج إليها للمصلحة الشرعية. س: طيب النووي يا شيخ يقول: لا أجعل أحدًا في حل سمّاني أو لقبني محي الدين، فهل يُعْرَض عنه؟ الشيخ: ما أدري والله عن صحة هذا عن النووي، لكن هذه ما هي بغِيبة، هذه مصلحة.","link":"https://binbaz.org.sa/fatwas/23508/هل-من-الغيبة-ذكر-بعض-الرواة-بما-يكرهون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الغيبة ذكر بعض الرواة بما يكرهون، واشتهروا به.mp3","categories":["الآداب والأخلاق","الحديث وعلومه"]},{"id":3922,"question":"الجمع بين مختلف الأحاديث؟","title":"كيف يتم الجمع بين الأحاديث المختلفة؟","answer":"الجواب: الظاهر من جهة حفظ الرواة، والقاعدة: من زاد تقبل منه الزيادة، هذه قاعدة، فإن الرواة يختلفون فإذا زاد بعضهم على بعض قُبلت الزيادة، إذا كان الزائد ثقة، حتى أخبار الناس اليوم إذا حدث حادث... أخبارهم، والقاعدة تقبل الزيادة إذا رواها الثقة.\nس: إذا كان الراوي بدون زيادة أوثق؟\nالشيخ: ولو، ما دامت الزيادة لا تماري ولا تخالف فما يضر، يقول الحافظ في النخبة: وزيادة راويهما (أي الصحيح والحسن) مقبولة، ما لم تقع منافية لمن هو أوثق، ما دام ما تنافي، هذا قال مائة، وذاك قال مائة وعشرين، هذا ما فيه كلام قصاراه أنه سقط على صاحب المائة ما انتبه للزيادة، وهذا حفظها، كذلك سقط على أحدهم الإبل والغنم وهذا حفظ الزيادة.","link":"https://binbaz.org.sa/fatwas/24140/كيف-يتم-الجمع-بين-الاحاديث-المختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين مختلف الأحاديث.mp3","categories":["الحديث وعلومه"]},{"id":3930,"question":"كأنه (البخاري) ما صح عنده حديث فيه صراحة في الغِيبة؟","title":"هل صح عند البخاري حديث في الغِيبة؟","answer":"الجواب: إن لم يأت بشيء، فهو اكتفى بهذا؛ لأنه ليس عنده شيء على شرطه بل رواه مسلم في الصحيح عن أبي هريرة  أن النبي ﷺ قال: الغِيبة ذكرك أخاك بما يكره، قيل: يا رسول الله إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول فقد اغتبته، وإن لم يكن فيه ما تقول فقد بَهَتّه رواه مسلم في الصحيح.  وفي حديث رواه أحمد وغيره بإسناد صحيح أن النبي ﷺ لما أسري به لما عرج به إلى السماء مر على قوم أظفارهم من نحاس يخمشون بها وجوههم وصدورهم فقال لجبرائيل: من هؤلاء؟ قال: هؤلاء الذين يأكلون لحوم الناس ويقعون في أعراضهم نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24149/هل-صح-عند-البخاري-حديث-في-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صح عند البخاري حديث في الغيبة.mp3","categories":["الحديث وعلومه"]},{"id":3944,"question":"إدخال الحديثين الأخيرين هنا (أحاديث الحَلِف باللات والآباء في باب مَنْ لم ير إكفار من قال ذلك متأوّلًا أو جاهلًا)؟","title":"بِمَ أمر الرسول ﷺ مَنْ حَلَفَ باللات والآباء؟","answer":"الجواب: لأن الرسول ﷺ ما كفّرهم؛ بل أمرهم ألا يحلفوا إلا بالله وحده، كان هذا جاريًا على ألسنتهم، فلما كانوا متأوّلين على الطريقة القديمة والعادة القديمة نهاهم عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24167/بم-امر-الرسول-ﷺ-من-حلف-باللات-والاباء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا أدخل البخاري أحاديث الحلف باللات والآباء في باب من لم ير إكفار من قال ذلك.mp3","categories":["الحديث وعلومه"]},{"id":4027,"question":"قوله في السند: حدثني والله أبو ذر؟","title":"حكم الحَلِف على الفتوى للتأكيد","answer":"الجواب: للتأكيد، مثل قوله: والله لأن يهدي الله بك رجلاً واحدًا خير لك من حمر النعم. يجوز للمحدث والمفتي أن يحلف على الفتوى إذا كانت عنده في غاية من الوضوح؛ للتأكيد للمستفتي أو للتلميذ إذا أراد أن يحدثه بشيء من باب التأكيد.","link":"https://binbaz.org.sa/fatwas/24263/حكم-الحلف-على-الفتوى-للتاكيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قوله في السند حدثني والله أبو ذر.mp3","categories":["الحديث وعلومه"]},{"id":4085,"question":"إذا قال: عبدالله، فهو عبدالله بن مسعود؟","title":"كيف يُعرف المقصود من العبادلة في الحديث؟","answer":"الجواب: لا، يختلف بحسب التلاميذ، إذا قال نافع: حدثنا عبدالله، فهو ابن عمر، وإذا قال سالم: عبدالله، فهو ابن عمر ..، وإذا قال الحارث بن سويد و... النخعي والأسود وأشباههم: حدثنا عبدالله، فهو عبدالله بن مسعود، وإذا قال أصحاب ابن الزبير: حدثنا عبدالله، فهو عبدالله بن الزبير، وإذا قال أصحاب عبدالله بن عمرو: حدثنا عبدالله، فهو عبدالله بن عمرو، يختلف بحسب التلاميذ، وهكذا أصحاب عبدالله بن عباس إذا قالوا: حدثنا عبدالله، يعني ابن عباس، فإذا قال سعيد بن جبير، وقال عمرو بن دينار، وأشباههم، فهو عبدالله بن عباس.","link":"https://binbaz.org.sa/fatwas/24325/كيف-يعرف-المقصود-من-العبادلة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/في سند الحديث إذا قال عبدالله، فهل هو عبدالله بن مسعود.mp3","categories":["الحديث وعلومه"]},{"id":4102,"question":"زيادة \"بيده الخير\"؟","title":"درجة زيادة \"بيده الخير\" في ذكر التهليل","answer":"الجواب: جاءت في بعض الروايات، لكنها خارج الصحيح، وذكرها المؤلفُ في \"الفتح\" فيما تقدَّم بإسنادٍ جيدٍ، بعض الروايات.","link":"https://binbaz.org.sa/fatwas/24342/درجة-زيادة-بيده-الخير-في-ذكر-التهليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة بيده الخير في قول لا إله إلا الله، وحده لا شريك له، له الملك..mp3","categories":["الحديث وعلومه"]},{"id":4124,"question":"حديث سبعة يظلهم الله يوم لا ظل إلا ظله، يقول هذا جاء في قوله ﷺ من تصدق بيمينه، يقول جاء مقلوب من تصدق بالشمال؟","title":"حكم رواية التصدق بالشمال ووهم الراوي","answer":"الجواب: هذه رواية، لكن المحفوظ في \"الصحيحين\": ورجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شماله ما تُنفق يمينه، وهم بعضُ الرواة فقال: تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم يمينُه ما تُنفق شماله، هذا وهمٌ من بعض الرواة، يقع بعض الأشياء في هذا، هذا نبّه عليه العلماء، ولا يضرّ؛ لأن \"الصحيحين\" رويا الشيء الصحيح وأثبتاه، فقد يقع من بعض الرواة غلط في بعض الروايات، هذا يقع في الصحيح وغير الصحيح، لكن أحاديث \"الصحيحين\" كلها محفوظة، سوى حديثٍ واحدٍ عند مسلم: إنَّ الله خلق التربة يوم السبت .. إلى آخره، وقع فيه بعضُ الغلط.","link":"https://binbaz.org.sa/fatwas/24369/حكم-رواية-التصدق-بالشمال-ووهم-الراوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم رواية التصدق بالشمال ووهم الراوي.mp3","categories":["الحديث وعلومه"]},{"id":4342,"question":"بعض طلاب العلم يخضع أسانيد البخاري ومسلم للدراسة والنقد، فيقول مثلاً لما يورد سند البخاري: هذا حديث حسن، ومسلم كذلك؟","title":"هل يوجد خلاف في قبول البخاري ومسلم؟","answer":"الجواب: ... الأئمة اتفقوا على قبول الصحيحين إلا أشياء يسيرة انتقدها الدارقطني في مسلم، وإلا الأئمة اتفقوا على قبول رواية الصحيحين، وإنها بحمد الله بعد الدراسة والعناية اتضحت سلامتها في جهة أسانيدها، والمؤلفان البخاري ومسلم قد اجتهدا في ذلك واختاراها من جملة أحاديث، رحمة الله عليهما، وأسانيدها واضحة.","link":"https://binbaz.org.sa/fatwas/24617/هل-يوجد-خلاف-في-قبول-البخاري-ومسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إخضاع أسانيد البخاري ومسلم للدراسة والنقد.mp3","categories":["الحديث وعلومه"]},{"id":4343,"question":"رواية أبي الزبير عن جابر؟","title":"ما حكم رواية أبي الزبير عن جابر عند مسلم؟","answer":"الجواب: مسلم رحمه الله اختارها؛ لأنه ظهر له منها أنه سمعه، اختار ما سمعه أبو الزبير.","link":"https://binbaz.org.sa/fatwas/24618/ما-حكم-رواية-ابي-الزبير-عن-جابر-عند-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رواية أبي الزبير عن جابر.mp3","categories":["الحديث وعلومه"]},{"id":4346,"question":"الراجح في معنى قولهم: هذا سند على شرط الشيخين أو على شرط مسلم؟ ما الراجح في هذا؟","title":"ما معنى \"على شرط الشيخين أو أحدهما\"؟","answer":"الجواب: يعني رجاله رجال الشيخين.","link":"https://binbaz.org.sa/fatwas/24621/ما-معنى-على-شرط-الشيخين-او-احدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الراجح في قولهم هذا سند على شرط الشيخين، أو على شرط مسلم.mp3","categories":["الحديث وعلومه"]},{"id":4789,"question":"قول الدارقطني: لولا البخاري ما جاء مسلم ولا راح؟","title":"معنى قول الدارقطني: لولا البخاري ما جاء مسلم ولا راح","answer":"من باب المبالغة - رحمه الله -، مسلم إمام عظيم، لكنه تخرج عن البخاري، واستفاد منه، وتتلمذ عليه؛ فبالغ الدارقطني.","link":"https://binbaz.org.sa/fatwas/25164/معنى-قول-الدارقطني-لولا-البخاري-ما-جاء-مسلم-ولا-راح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى قول الدارقطني لولا البخاري ما جاء مسلم ولا راح.mp3","categories":["الحديث وعلومه"]},{"id":4791,"question":"إذا خالف الثقة الثقات، وليسوا أوثق؟","title":"ما الحكم إذا خالف الثقة ثقاتٍ ليسوا أوثق منه؟","answer":"يطلب الترجيح من طرق أخرى، إما الأوثق، أو هذا صرح بالسماع، وهذا ما صرح بالسماع، أو هذا له شواهد، وهذا ما له شواهد، يرجح من طريق آخر.","link":"https://binbaz.org.sa/fatwas/25166/ما-الحكم-اذا-خالف-الثقة-ثقات-ليسوا-اوثق-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الحكم إذا خالف الثقة الثقات، وليسوا أوثق.mp3","categories":["الحديث وعلومه"]},{"id":4795,"question":"من أدرك النبي ﷺ، ولم يلقه؟","title":"هل يُعدُّ صحابيًّا من أدرك النبي ولم يلقه؟","answer":"هذا ما يسمى \"صحابي\"، يسمى \"تابعي\" مثل الصنابحي، وكعب الأحبار، هؤلاء يقال لهم: تابعيون، وإن كانوا أدركوا النبي ﷺ، لكن ما لقوه، مات ولم يلقوه، قدموا المدينة بعد موته ﷺ.","link":"https://binbaz.org.sa/fatwas/25176/هل-يعد-صحابيا-من-ادرك-النبي-ولم-يلقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أدرك النبي ولم يلقه، هل هو صحابي.mp3","categories":["الحديث وعلومه"]},{"id":4984,"question":"إذا كان الحديث بمجموع طرقه لا يتقوّى إلى الحَسَن لغيره وكان ضعيفًا؛ لا يُعمل به في الرقائق؟","title":"ما حكم رواية الحديث الضعيف والعمل به؟","answer":"الجواب: لا، ما تَثْبُت به سُنة لكن بس يُشَجَّع به، من باب التشجيع على الشيء الثابت، يعني إن كان في الصلاة والصيام، يُشَجّع على الشيء الثابت.\nس: يجوز العملُ به؟\nالشيخ: يكون من باب التشجيع، من باب الترغيب في شيء ثابت، لا يُثْبِت الحكم هو، الضعيف ما يثبت به حكم لكن يشجع به على أحكام ثابتة، مثل في فضل صيام رمضان، في فضل صيام يوم عرفة، في فضل صيام الإثنين والخميس، هي ثابتة بالأدلة الصحيحة، لكن إذا جاءت أحاديث فيها ترغيب؛ من باب التشجيع.","link":"https://binbaz.org.sa/fatwas/28483/ما-حكم-رواية-الحديث-الضعيف-والعمل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم رواية الحديث الضعيف والعمل به؟.mp3","categories":["الحديث وعلومه"]},{"id":5432,"question":"ما الفرق بين الحديث القدسي والحديث النبوي؟","title":"ما الفرق بين الحديث القدسي والحديث النبوي؟","answer":"الجواب: القدسي يُنسَب إلى الله، يقول الله جل وعلا، لكن النبيَّ ﷺ ينقله عن ربِّه فيُقال له: قدسي، والذي لا يقوله عن ربِّه يُقال أنه حديث النبي ﷺ، مثل: إنما الأعمال بالنّيات، وبُنِيَ الإسلامُ على خمسٍ هذا من كلام النبي ﷺ. س: يعني: معناها من الله ولفظها من النبي ﷺ؟ ج: وحيٌ من الله، لكن ألفاظها ألفاظُ النبي ﷺ، أوحى الله إليه معناها، وتكلَّم بها النبيُّ ﷺ. أمَّا القدسي فمثل: قال الله جل وعلا: يا ابن آدم كذا وكذا، إني حرَّمتُ الظلمَ على نفسي وجعلتُه بينكم مُحرَّمًا، فلا تظالموا، يا ابن آدم، كلكم ضالٌّ إلا مَن هديتُه، فاستهدوني أهدكم .. إلى آخره. س: له حكم القرآن؟ ج: لا، هو كلام الله، لكن ليس له حكم القرآن. س: يكون اللفظ من الله ولكن ليس متواترًا؟ ج: يكون ليس له حكم القرآن ولو هو غير متواتر، ليس له حكم القرآن.[1]","link":"https://binbaz.org.sa/fatwas/31220/ما-الفرق-بين-الحديث-القدسي-والحديث-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 048.mp3","categories":["الحديث وعلومه"]},{"id":5447,"question":"في أحد العلماء الكبار في الجرح والتعديل وعِلم الرجال يقول: إنه في العصر الحديث، يقول إن في البخاري ومسلم، أو في أحدهما بعض الأحاديث الضعيفة القليلة؟","title":"هل في البخاري أو مسلم أحاديث ضعيفة؟","answer":"الجواب: هذا شيء قد قاله بعض أهل العلم، لكن ما هو مُسلَّم، والصواب قبول ما فيهما. س: هل وجد شيء، ولو حديث واحد؟ الشيخ: فيه حديث لمسلم، حديث رواه، وهم فيه بعض الرواة، حديث: إن الله خلق التربة يوم السبت وجعل مخلوقاته في سبعة أيام، السبت إلى الجمعة، وهذا مخالف لنص القرآن؛ لأن الله خلق الخلق في ستة أيام، هذا وهم من بعض الرواة، رفعه إلى النبي ﷺ، وإنما هو عن كعب الأحبار، غلط من بعض الرواة في رفعه، رفعه من طريق أبي هريرة، هذا لا شك أنه وهم كما قال البخاري وغيره، رواه مسلم لكنه وهم، رفع إلى النبي ﷺ من طريق أبي هريرة، وإنما الصواب أن أبا هريرة رواه عن كعب، ما هو عن النبي ﷺ، فوهم بعض الرواة ورفعه إلى النبي ﷺ، وإنما هو عن كعب الأحبار. وفيه بعض مرويات مسلم... تكلم بعضهم فيها أنه يأخذ السماء بيمينه، والأرض بشماله... والصواب أنه لا بأس به؛ لأن الأدلة الدالة على اليمين تدل على الشمال، ولكن كلتا اليدين يمين مباركة، كلتا يديه يمين مباركة، وليست بالشمال، فكأنها في الفضل يمين.  سؤال: التلقي بالقبول مُقدَّم على كثرة الطرق؛ لإفادة العلم اليقيني؟ الشيخ: قد يُستفاد بكثرة الطرق أكثر، إذا رواه من طرق جيدة قد يُستفاد منها، تدل على العلم أكثر، لكن مزية الشيخين كونهما اتفقا عليه، ورأياه صحيحًا، وتلقته الأمة، هذه مزية خاصة.[1]","link":"https://binbaz.org.sa/fatwas/31259/هل-في-البخاري-او-مسلم-احاديث-ضعيفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 002.mp3","categories":["الحديث وعلومه"]},{"id":5449,"question":"قول الدارقطني: لولا البخاري ما جاء مسلم ولا راح؟","title":"ما معنى عبارة \"لولا البخاري ما جاء مسلم\"؟","answer":"الجواب: من باب المبالغة - رحمه الله -، مسلم إمام عظيم، لكنه تخرَّج عن البخاري، واستفاد منه، وتتلمذ عليه؛ فبالغ الدارقطني.[1]","link":"https://binbaz.org.sa/fatwas/31266/ما-معنى-عبارة-لولا-البخاري-ما-جاء-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 005.mp3","categories":["الحديث وعلومه"]},{"id":5450,"question":"أيش الفرق بين شرط البخاري وشرط الشيخين؟","title":"ما الفرق بين شرط البخاري وشرط الشيخين؟","answer":"الجواب: مثل ما سمعت، شرط البخاري أقوى من العناية بالضبط والاتصال. س: شرط الشيخين داخل في شرط البخاري؟ الشيخ: لكن فرق بينهما، لكن إذا كان شرط البخاري وحده: أقوى من شرط مسلم، فإذا اتفقا اجتمع شرطهما، فإذا انفرد أحدهما صار شرط البخاري أقوى من شرط مسلم، هذا مقصوده.[1]","link":"https://binbaz.org.sa/fatwas/31267/ما-الفرق-بين-شرط-البخاري-وشرط-الشيخين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 006.mp3","categories":["الحديث وعلومه"]},{"id":5454,"question":"أقل الرجال في السند العالي؟","title":"كم أقل عدد للرجال في السند العالي للحديث؟","answer":"الجواب: ما له حد، أقله شيخان، التابعي، والصحابي، مثال: مالك عن نافع عن ابن عمر، هذه أقل شيء، هذا أعلى شيء، ما بينه وبين الصحابي إلا واحد مثل مالك، والثوري، ومثل الأئمة الكبار كالأوزاعي، بينهم وبين الصحابة واحد، والنزول لا حد له.[1]","link":"https://binbaz.org.sa/fatwas/31289/كم-اقل-عدد-للرجال-في-السند-العالي-للحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 010.mp3","categories":["الحديث وعلومه"]},{"id":5460,"question":"تُقبل الرواية عن المبتدع؟","title":"هل تُقبل رواية الحديث عن المبتدع؟","answer":"الجواب: المبتدع فيه تفصيل، تَقَدَّم؛ الداعي إلى حاله، وغير الداعي إلى حاله، إذا روى ما يقوَّي بدعته، وإذا روى ما لا يقويها، فيه تفصيل، تَقَدَّم في السبب التاسع.[1]","link":"https://binbaz.org.sa/fatwas/31307/هل-تقبل-رواية-الحديث-عن-المبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 016.mp3","categories":["الحديث وعلومه"]},{"id":5461,"question":"إذا وجد لأهل العلم كلام في ديانة الراوي، ولم يوجد لهم كلام في حفظه، وضبطه؟","title":"ما الفرق بين العدالة والضبط في رواة الحديث؟","answer":"الجواب: هذا يتعلق بالعدالة، فالعدالة شيء، والضبط شيء آخر: قد يكون الرجل عدلًا لكن ليس بضابط؛ عنده سوء حفظ. وقد يكون ضابطًا جيدًا من جهة الحفظ، لكن ليس بعدل؛ عنده الفجور، والمعاصي، أو البدع.[1]","link":"https://binbaz.org.sa/fatwas/31308/ما-الفرق-بين-العدالة-والضبط-في-رواة-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 017.mp3","categories":["الحديث وعلومه"]},{"id":5648,"question":"إرسال الثِّقات؟","title":"ما حكم مُرْسَل الثقات في رواية الحديث؟","answer":"الجواب: لا، المرسل مطلقًا ما هو بحُجَّة مطلقًا، إلا ما قيل في مرسل سعيد بن المسيب، المرسل فيه كلام، بحث طويل لأهل العلم، وهذا الكلام ما هو بمحرر.[1]","link":"https://binbaz.org.sa/fatwas/31684/ما-حكم-مرسل-الثقات-في-رواية-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/alaistiqama 010.mp3","categories":["الحديث وعلومه"]},{"id":5710,"question":"بالنسبة للحديث الضعيف هل يعمل به؟","title":"هل يعمل بالحديث الضعيف؟","answer":"الجواب: الحديث الضعيف أقسام، إن كان حسنا جيد الإسناد يعمل به، وإن كان ضعيف المرة فلا يعمل به، الضعيف المرة إذا كان في إسناده كذاب، أو في إسناده سيئ الحفظ جدًا، أو منقطع الإسناد لا يعمل به.","link":"https://binbaz.org.sa/fatwas/1014/هل-يعمل-بالحديث-الضعيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_39.mp3","categories":["الحديث وعلومه"]},{"id":6831,"question":"اشتهر عند كثير من الناس العمل بالحديث الضعيفـ بحجة فضائل الأعمال، دون مراعاة شروط العلماء بذلك، حتى صار ذلك ديدنهم؛ مما أفقدهم التحسس، والاهتمام بالدليل الشرعي الصحيح الثابت عن الله ورسوله ﷺ مما أوقعهم في البدع، وبالتالي في الشرك من حيث الغلو في رسول الله ﷺ مما أدى بهم إلى الاستغاثة به، ودعائه اعتمادًا على غير دليل، أو على من زلت قدمه، وقل علمه بما كان عليه السلف الصالح، نرجو من سماحتكم التوجيه وجزاكم الله خيرًا.","title":"حكم العمل بالحديث الضعيف في فضائل الأعمال","answer":"الجواب: الأحاديث الضعيفة لا يعتمد عليها في إثبات شيء من الشرع، وهكذا الحكايات، والمنامات، والسواليف، والآثار عن بعض السلف، كلها لا يعتمد عليها في إثبات الحكم الشرعي، إنما الأحكام تثبت بالآيات القرآنية، أو بالأحاديث الثابتة عن رسول الله -عليه الصلاة، والسلام- أو بما يأتي عن الخلفاء الراشدين، أما الأحاديث الضعيفة لا، لا يثبت فيها حكم، لا واجب، ولا سنة، ولا تحريم، ولا كراهة، وإنما يثبت هذا في الأحاديث. لكن ذكر العلماء أن الأحاديث الضعيفة تذكر من باب الترغيب في الأشياء المعروفة من الدين، لا في الأشياء المحدثة، ولهذا يتساهلون في الأحاديث الضعيفة، لا الموضوعة، في الأحاديث الضعيفة التي لم تستقم أسانيدها لكنها غير مكذوبة، أما المكذوب، الموضوع لا، ما يذكر أبدًا إلا لبيان أنه كذب، فلا يحتج به أبدًا. لكن الأحاديث التي فيها ضعف، إما راوي سيئ الحفظ، أو راوي عنده شيء من الفسق، أو ما أشبه مما يقال: إن حديثه ضعيف، هذا يذكر عند العلماء في مقام الترغيب في الأعمال الصالحة المعروفة، مثل: الأحاديث الضعيفة في مقام الصدقات، الصدقات معروفة، أمر الصدقة فيها الآيات، وفيها الأحاديث الصحيحة، فإذا جاء بعض الأحاديث الضعيفة في فضل الصدقات؛ ذكروه، أو في فضل الصلاة، والتنفل، أو في فضل التسبيح، أو التهليل، والأذكار، كل هذه أمور معلومة، فقد يتساهلون في الأحاديث الضعيفة؛ لأن أصلها معروف، ولأن العبادات التي جاءت بها في الأحاديث الضعيفة أمر معلوم من الكتاب، والسنة، هذا وجه. أما الضعيف بنسبة السنة عبادة جديدة، لا. الأحاديث الضعيفة لا يثبت بها عبادة، ولا تحريم، ولا مكروه، ولا واجب، فالذين يثبتون بها عبادات جديدة غالطون.","link":"https://binbaz.org.sa/fatwas/2716/حكم-العمل-بالحديث-الضعيف-في-فضاىل-الاعمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1215.mp3","categories":["الحديث وعلومه"]},{"id":6849,"question":"سمعت من يقول: بأن هناك بعض الأحاديث غير الصحيحة في صحيحي البخاري ومسلم، فنرجو الرد على  هذه الشبهة، جزاكم الله خيرًا؟","title":"الرد على من يطعن في أحاديث الصحيحين","answer":"الجواب: هذا غير صحيح، الصحيحان قد تلقته الأمة بالقبول، وهذه أحاديثهم المعروفة بالصحة، وأنها حجة سوى حديث واحد وقع فيه سهو من بعض الرواة، فنسبه إلى النبي ﷺ وهو من كلام كعب الأحبار في أصح قولي المحدثين، وهو حديث أبي هريرة في صحيح مسلم: \"أن الله خلق الدنيا في سبعة أيام، أولها يوم السبت، وآخرها الجمعة\" وهذا وهم، وإنما هي في ستة أيام، أولها يوم الأحد، هذا المحفوظ كما دل عليه القرآن العظيم في ستة أيام.  هذا حديث واحد في صحيح مسلم، وهم فيه بعض الرواة، فنسبه إلى النبي ﷺ وإنما هو عن أبي هريرة، عن كعب الأحبار، لا عن النبي ﷺ وقد وهم فيه كعب الأحبار، وهو تابعي.","link":"https://binbaz.org.sa/fatwas/2743/الرد-على-من-يطعن-في-احاديث-الصحيحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1243.mp3","categories":["الحديث وعلومه"]},{"id":6859,"question":"في هذا العصر تكلم بعض مدعي العلم أن في صحيح البخاري، ومسلم أحاديث غير صحيحة، فهل هذا صحيح؟","title":"الادعاء بأن صحيحي البخاري ومسلم بهما أحاديث ضعيفة","answer":"الجواب: ليس بصحيح، الكتابان عظيمان، وصحيحان، وتلقتهما الأمة بالقبول، تلقاهما أهل العلم بالقبول، والتسليم، فهما كتابان عظيمان، وصحيحان، سوى ألفاظ يسيرة قد يحتج عليها بأدلة أخرى من نفس الصحيح، ألفاظ قد يغلط فيها بعض الرواة، لكن نفس المتن صحيح.  فالأحاديث صحيحة، ومتلقاة بالقبول، فيجب العمل بها سوى حديث واحد -فيما أعلم- وقع في صحيح مسلم، ووقع فيه بعض الغلط، ليس كله غلط، ولكن وقع فيه بعض الغلط، وهو أن حديث أبي هريرة عن النبي ﷺ أنه قال: خلق الله التربة يوم السبت... ثم عدد، فجعل الخلق في سبعة أيام، من السبت إلى الجمعة، وقد حفظ العلماء على أنه وهم من بعض الرواة، وإنما هو عن كعب الأحبار، ليس عن أبي هريرة، ولكنه عن كعب الأحبار، فغلط كعب في ذلك، فهذا وهم في رفعه، وإنما هو من كلام كعب الأحبار، فوهم فيه بعض الرواة. هذا وقع في صحيح مسلم، وعلم عدم صحة متنه مما دل عليه كتاب الله، وسنة رسوله ﷺ من أن الله خلق الخلق في ستة أيام، لا في سبعة أيام، فوقعت غلطة في ذكر أنه خلق التربة يوم السبت، والصواب أن أول الخلق كان في يوم الأحد، وانتهى في يوم الجمعة ستة أيام، فلا أعلم شيئًا حكم عليه بعدم الصحة، سوى هذا الحديث. هناك ألفاظ أخرى وقعت في صحيح مسلم، لكن لا في أصل الحديث، بل في بعض الألفاظ في مثل ما في صلاة الكسوف: أن الرسول ﷺ ركع في بعض الركعات ثلاث ركوعات، أو أربع ركوعات، هذا حكم البخاري، وجماعة بأنه وهم. والصواب: أنه إنما ركع ركوعين في كل ركعة، ولكن هذا ليس أمرًا مجمعًا عليه، بل محل خلاف بين أهل العلم، في هل صح ذكر الركوعات الثلاث، والأربع، أم لا؟، وهذاوقع في صحيح مسلم -رحمه الله-.  فالحاصل: أن هذين الكتابين صحيحان في الجملة متلقيان بالقبول، وليس فيهما حديث باطل مجمع عليه، سوى حديث أبي هريرة الذي ذكرت لكم، وهو ما وقع فيه من غلط عد الأيام فقط.","link":"https://binbaz.org.sa/fatwas/2735/الادعاء-بان-صحيحي-البخاري-ومسلم-بهما-احاديث-ضعيفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1235.mp3","categories":["الحديث وعلومه"]},{"id":6862,"question":"في هذا العصر تكلم بعض مدعي العلم أن في صحيح البخاري، ومسلم أحاديث غير صحيحة، فهل هذا صحيح؟","title":"الادعاء بأن صحيحي البخاري ومسلم بهما أحاديث ضعيفة","answer":"الجواب: ليس بصحيح، الكتابان عظيمان، وصحيحان، وتلقتهما الأمة بالقبول، تلقاهما أهل العلم بالقبول، والتسليم، فهما كتابان عظيمان، وصحيحان، سوى ألفاظ يسيرة قد يحتج عليها بأدلة أخرى من نفس الصحيح، ألفاظ قد يغلط فيها بعض الرواة، لكن نفس المتن صحيح.  فالأحاديث صحيحة، ومتلقاة بالقبول، فيجب العمل بها سوى حديث واحد -فيما أعلم- وقع في صحيح مسلم، ووقع فيه بعض الغلط، ليس كله غلط، ولكن وقع فيه بعض الغلط، وهو أن حديث أبي هريرة عن النبي ﷺ أنه قال: خلق الله التربة يوم السبت... ثم عدد، فجعل الخلق في سبعة أيام، من السبت إلى الجمعة، وقد حفظ العلماء على أنه وهم من بعض الرواة، وإنما هو عن كعب الأحبار، ليس عن أبي هريرة، ولكنه عن كعب الأحبار، فغلط كعب في ذلك، فهذا وهم في رفعه، وإنما هو من كلام كعب الأحبار، فوهم فيه بعض الرواة. هذا وقع في صحيح مسلم، وعلم عدم صحة متنه مما دل عليه كتاب الله، وسنة رسوله ﷺ من أن الله خلق الخلق في ستة أيام، لا في سبعة أيام، فوقعت غلطة في ذكر أنه خلق التربة يوم السبت، والصواب أن أول الخلق كان في يوم الأحد، وانتهى في يوم الجمعة ستة أيام، فلا أعلم شيئًا حكم عليه بعدم الصحة، سوى هذا الحديث. هناك ألفاظ أخرى وقعت في صحيح مسلم، لكن لا في أصل الحديث، بل في بعض الألفاظ في مثل ما في صلاة الكسوف: أن الرسول ﷺ ركع في بعض الركعات ثلاث ركوعات، أو أربع ركوعات، هذا حكم البخاري، وجماعة بأنه وهم. والصواب: أنه إنما ركع ركوعين في كل ركعة، ولكن هذا ليس أمرًا مجمعًا عليه، بل محل خلاف بين أهل العلم، في هل صح ذكر الركوعات الثلاث، والأربع، أم لا؟، وهذاوقع في صحيح مسلم -رحمه الله-.  فالحاصل: أن هذين الكتابين صحيحان في الجملة متلقيان بالقبول، وليس فيهما حديث باطل مجمع عليه، سوى حديث أبي هريرة الذي ذكرت لكم، وهو ما وقع فيه من غلط عد الأيام فقط.","link":"https://binbaz.org.sa/fatwas/2735/الادعاء-بان-صحيحي-البخاري-ومسلم-بهما-احاديث-ضعيفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1235.mp3","categories":["الحديث وعلومه"]},{"id":9060,"question":"ننتقل إلى أسئلة أخرى عبر رسالة الأخ (ع. ج) من جمهورية مصر العربية، أخونا يسأل هذا السؤال ويقول: يذكر الشيخ الألباني في بعض كتبه الأحاديث النبوية ويقول: صحيحة، ويعزوها إلى سلسلته الصحيحة، وأحيانًا يقول: الحديث ضعيف ويسنده إلى سلسلته الضعيفة ولا يعزو الأحاديث إلى مصادرها الأصلية كـالبخاري ومسلم وأصحاب السنن والمسانيد والمعاجم، فهل يتمشى هذا مع الأمانة العلمية في إغفال ذكر سلف هذه الأمة من المحدثين الذين كانوا سببًا في إيصال الحديث لدينا، وكذلك إغفال أقوالهم في الحديث، أرجو أن توجهونا حيال هذا، جزاكم الله خيرًا؟","title":"منهج الألباني رحمه الله في دراسة الأحاديث وعزوها","answer":"الجواب: الشيخ محمد ناصر الدين الألباني من خواص إخواننا المعروفين بالاستقامة وحسن العقيدة والسيرة والنشاط في جمع الحديث وبيان صحيحه من سقيمه فهو مشكور ومعروف لدينا وله في هذا جهود مباركة وأعمال جليلة نسأل الله لنا وله المزيد من التوفيق مع صلاح النية والعمل.\nولكنه مثل غيره من أهل العلم ليس معصومًا، قد تقع له بعض الأخطاء وبعض الغلط في التصحيح والتضعيف وفي الآراء ولكنه يشكر على اجتهاده وعلى قصده الخير وإذا أخطأ فلا مانع من التنبيه من أهل العلم أن ينبهوه وأن يكتبوا إليه حتى يحصل التعاون على البر والتقوى، عملًا بقوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، هكذا شأن العلماء في قديم الدهر وحديثه يتعاونون وينصح بعضهم بعضًا ولا يسب بعضهم بعضًا ولا يحتقره ولا يعيبه ولا يغتابه ولكن ينصح له ويعينه على الخير وينبهه إذا أخطأ.\nوالشيخ الألباني ليس ممن يتركون العزو بل هو يعزو الأحاديث إلى مصادرها وإنما يختصر في بعض الأحيان في بعض الكتب فيعزوها إلى الصحيحة أو إلى الضعيفة، وأنت في إمكانك ترجع إلى الصحيحة وتجد فيها العزو إلى البخاري إلى مسلم إلى أبي داود إلى النسائي إلى الترمذي إلى غيرهم، وتجد الكلام في الرجال والأسانيد بالتصحيح والتضعيف ونقل كلام العلماء في ذلك، ليس كما ذكره السائل بل الشيخ الألباني قرأنا كتبه واطلعنا على طريقته، فهو يعزو الأحاديث إلى مصادرها وينبه على ما فيها حسب اجتهاده، لكن إذا اختصر في بعض الأحيان وقال: ذكرته في الصحيحة، أو ذكرته في الضعيفة، أو ذكرته في صحيح الجامع، أو في صحيح كذا أو في ضعيف كذا معناه أنه يرشدك إلى أن ترجع إلى ذلك حتى تجد مطلوبك من البحث والكلام على السند هكذا، هكذا عمله وهكذا طريقته.\nفالواجب عليك أيها السائل! أن تتقي الله وأن تنصف أخاك، وفق الله الجميع، نعم.\nالمقدم: جزاكم الله خيرًا، إذًا يرى سماحة الشيخ عبدالعزيز أن الشيخ الألباني فيما إذا أرشد إلى خطأ وقع في كتبه أنه سيصحح؟\nالشيخ: إذا ظهر له الصح، إذا ظهر له ذلك، إذا ظهر له أن الذي أرشده أصاب وهو أخطأ صححه، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7218/منهج-الالباني-رحمه-الله-في-دراسة-الاحاديث-وعزوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17806.mp3","categories":["الحديث وعلومه"]},{"id":9357,"question":"من هم أصحاب الأمهات الست؟ وما هي هذه الأمهات؟ السؤال لا زال لأخينا من اليمن؟","title":"المقصود بالأمهات الست","answer":"الجواب: الأمهات الست هي: صحيح البخاري، وصحيح مسلم، وسنن أبي داود، وسنن الترمذي، وسنن النسائي، وسنن ابن ماجة، هذه هي الأمهات الست إذا قالوا: الأمهات الست، أو الكتب الستة هي هذه الستة، لهؤلاء الستة: البخاري ومسلم وأبي داود والترمذي والنسائي وابن ماجة . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7521/المقصود-بالامهات-الست","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18511.mp3","categories":["الحديث وعلومه"]},{"id":9804,"question":"السائل في ختام رسالته يقول: أرجو أن ترشدوني إلى كتاب أحاديث جيد؟","title":"كتب في الحديث ينصح بقراءتها","answer":"الجواب: من أحسن الكتب في هذا لطالب العلم كتاب بلوغ المرام، كتاب جيد ومفيد ومحرر على أبواب الأحكام، وهو كتاب جيد ومفيد، بلوغ المرام للحافظ ابن حجر، هذا ننصح بحفظه وتدبر ما فيه من الأحاديث الصحيحة، وهناك أحاديث ضعيفة فيه قليلة بين حالها ونبه عليها.\nومن الكتب الجيدة أيضًا والمختصرة عمدة الحديث للشيخ عبدالغني بن علي بن سرور المقدسي رحمه الله فيها جملة طيبة من الأحاديث، أربعمائة وزيادة قليلة، نافعة مفيدة، ولكن أنفع منها بلوغ المرام؛ لأنه أوفى منها وأكثر.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7971/كتب-في-الحديث-ينصح-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19703.mp3","categories":["الحديث وعلومه"]},{"id":10661,"question":"ما هو الفرق بين الحديث القدسي والقرآن، وكلاهما كلام الله ؟","title":"الفرق بين القرآن والحديث القدسي والحديث النبوي","answer":"الجواب: القدسي ما ينقله الرسول ﷺ عن ربه من غير القرآن يقال له: قدسي، ويقال له: كلام الله، لكن ليس له حكم القرآن من جهة أنه معجزة، من جهة أنه لا يمس إلا بطهارة، من جهة أنه يقرأ به في الصلاة لا، لكن له حكم كلام الله؛ بأنه يقال: هذا كلام الله، مثل قوله ﷺ مما حكاه عن ربه: يقول الله عز وجل: يا عبادي! إني حرمت الظلم على نفسي وجعلته بينكم محرماً فلا تظالموا، يا عبادي! كلكم ضال إلا من هديته فاستهدوني أهدكم..... الحديث، فهذا يقال له: قدسي، ويقال له: كلام الله، ولكن ليس له حكم القرآن من جهة أنه معجزة، ومن جهة أن يقرأ به في الصلاة، ومن جهة أنه له حكم المصحف لا، أما كلام الرسول ﷺ، فهذا ينسب إلى الرسول ﷺ، مثل: قوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى مثل قوله ﷺ: لا تقبل صلاة بغير طهور، ولا صدقة من غلول هذا يقال له: هذا كلام النبي ﷺ، وإن كان شرعاً من الله وتعليماً من الله جل وعلا أوحاه الله إليه، لكنه من كلام النبي ﷺ ما نسبه إلى الله، فيعتبر من كلام النبي ﷺ، لكنه تشريع من الله وأمر من الله يجب اعتماده.\nوالأقسام ثلاثة:\nالقرآن كلام الله منزل غير مخلوق يقرأ به في الصلاة، وهو معجزة من المعجزات وله حكم المصحف.\nالثاني: كلام الله الذي ليس فيه قرآن، بل مما نقله الرسول ﷺ عن ربه جل وعلا، ويقال له: الكلام القدسي، فهذا ينسب إلى الله، ولكن ليس له حكم القرآن من جهة الإعجاز، والقراءة في الصلاة، وأن لا يمس إلا بطهارة.\nوالنوع الثالث: كلام النبي ﷺ، الذي يثبت عنه ﷺ، ولكن لا ينسبه إلى الله، فهذا يقال له: سنة، ويقال له: كلام النبي ﷺ وهو حجة، وهو واجب الاتباع، وهو .... شرع الله، لكنه لا ينسب إلى الله، ما يقال: هذا كلام الله. نعم.","link":"https://binbaz.org.sa/fatwas/8850/الفرق-بين-القران-والحديث-القدسي-والحديث-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32916.mp3","categories":["الحديث وعلومه"]},{"id":10669,"question":"ما هو الفرق بين الحديث القدسي والقرآن، وكلاهما كلام الله ؟","title":"الفرق بين القرآن والحديث القدسي والحديث النبوي","answer":"الجواب: القدسي ما ينقله الرسول ﷺ عن ربه من غير القرآن يقال له: قدسي، ويقال له: كلام الله، لكن ليس له حكم القرآن من جهة أنه معجزة، من جهة أنه لا يمس إلا بطهارة، من جهة أنه يقرأ به في الصلاة لا، لكن له حكم كلام الله؛ بأنه يقال: هذا كلام الله، مثل قوله ﷺ مما حكاه عن ربه: يقول الله عز وجل: يا عبادي! إني حرمت الظلم على نفسي وجعلته بينكم محرماً فلا تظالموا، يا عبادي! كلكم ضال إلا من هديته فاستهدوني أهدكم..... الحديث، فهذا يقال له: قدسي، ويقال له: كلام الله، ولكن ليس له حكم القرآن من جهة أنه معجزة، ومن جهة أن يقرأ به في الصلاة، ومن جهة أنه له حكم المصحف لا، أما كلام الرسول ﷺ، فهذا ينسب إلى الرسول ﷺ، مثل: قوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى مثل قوله ﷺ: لا تقبل صلاة بغير طهور، ولا صدقة من غلول هذا يقال له: هذا كلام النبي ﷺ، وإن كان شرعاً من الله وتعليماً من الله جل وعلا أوحاه الله إليه، لكنه من كلام النبي ﷺ ما نسبه إلى الله، فيعتبر من كلام النبي ﷺ، لكنه تشريع من الله وأمر من الله يجب اعتماده.\nوالأقسام ثلاثة:\nالقرآن كلام الله منزل غير مخلوق يقرأ به في الصلاة، وهو معجزة من المعجزات وله حكم المصحف.\nالثاني: كلام الله الذي ليس فيه قرآن، بل مما نقله الرسول ﷺ عن ربه جل وعلا، ويقال له: الكلام القدسي، فهذا ينسب إلى الله، ولكن ليس له حكم القرآن من جهة الإعجاز، والقراءة في الصلاة، وأن لا يمس إلا بطهارة.\nوالنوع الثالث: كلام النبي ﷺ، الذي يثبت عنه ﷺ، ولكن لا ينسبه إلى الله، فهذا يقال له: سنة، ويقال له: كلام النبي ﷺ وهو حجة، وهو واجب الاتباع، وهو .... شرع الله، لكنه لا ينسب إلى الله، ما يقال: هذا كلام الله. نعم.","link":"https://binbaz.org.sa/fatwas/8850/الفرق-بين-القران-والحديث-القدسي-والحديث-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32916.mp3","categories":["الحديث وعلومه"]},{"id":10726,"question":"الزميل محمد سعيد الصفار من الرياض بعث برسالة قال فيها: بسم الله الرحمن الرحيم، سماحة الشيخ عبدالعزيز بن عبدالله بن باز حفظه الله، سؤال إلى سماحتكم في هذا البرنامج نور على الدرب، وهو كما يلي: نسمع ونقرأ بين الحين والآخر لبعض المشايخ المعروفين إنكاراً لصحة بعض الأحاديث الواردة في صحيحي البخاري ومسلم ، وبعض كتب الصحاح الأخرى، ويكون إنكارهم لصحتها بعد تمحيصها بعقولهم كما يقولون، أي: أن المعول عليه عندهم في صحة الأحاديث هي عقولهم فقط، ومن ذلك ما قرأناه إنكاراً لأحاديث المهدي والدجال ونزول عيسى ابن مريم، والسؤال يا سماحة الشيخ! هل يجوز لأحد من علماء المسلمين مهما كان قدره أن ينكر صحة بعض الأحاديث الواردة في الصحاح، التي أجمع علماء الأمة على صحتها وتقديم أصحابها، خصوصاً صحيحي البخاري ومسلم بعقله فقط؟ وهل يمكن يا سماحة الشيخ! أن تبحثوا هذا الموضوع في المجمع الفقهي في رابطة العالم الإسلامي لأهميته، حيث أنه مع كثرة العلماء وإنكار كل منهم ما لا يروق له من الأحاديث، قد يتسرب الشك في نفوس عوام المسلمين في صحة أغلب أحاديث السنة المطهرة، ثم إذا رد أحد أصحاب الفضيلة حديثاً في البخاري ومسلم ، فما الذي يجعلنا نصدق بقية الأحاديث، خاصة التي جاءت بسند هذا الحديث المردود، أرجو التفصيل يا سماحة الشيخ! جزاكم الله خيراً؟","title":"الحذر من تحكيم العقول في رد الأحاديث الصحيحة","answer":"الجواب: الأحاديث التي جاءت في الصحيحين بأسانيدهما المعروفة، كلها عند أهل العلم متلقاة بالقبول، ومحكوم بصحتها ولا يجوز لأحد أن يردها، بل يجب قبولها كما قبلها العلماء قبلنا، والذين ردوا أحاديث الدجال أو أحاديث المسيح ابن مريم ، أو أحاديث يأجوج ومأجوج ، قد غلطوا في هذا غلطاً عظيماً وقالوا قولاً باطلاً، لا يجوز اتباعهم عليه ولا تقليدهم فيه، بل يجب عليهم التوبة من ذلك والرجوع إلى ما قاله أهل العلم في إثباتها وصحتها، وهكذا من رد غيرها من الأحاديث الثابتة في الصحيحين لا يلتفت إلى قوله، وليست العقول محكمة في أحاديث الرسول ﷺ، بل الأحاديث تتلقى عن الرسول ﷺ بالأسانيد الصحيحة التي بينها أهل العلم، إذا جاء الحديث من طريق الثقات في الصحيحين أو غيرهما سليماً من العلل وجب أن يقبل، ولا يجوز أن يحكم الرأي في رده من دون حجة شرعية، بل يجب على أهل العلم والإيمان قبول الأحاديث الصحيحة، والاحتجاج بها، والاعتماد عليها، سواء كانت متواترة أو كانت من طريق الآحاد ولا يجوز أبداً أن يقال: هذا من طريق الآحاد، فلا يقبل، كل هذا باطل وخلاف ما أجمع عليه أهل العلم، بل ما صحت به الأخبار عن رسول الله عليه الصلاة والسلام يجب قبوله والأخذ به، حسب ما بينه أهل العلم، ولا يجوز الاعتراض على ذلك بما رآه المتكلمون من تحكيم العقول، وما سلكه بعض المتأخرين في هذا الباب تقليداً لأهل الكلام، وسيراً على منهاجهم في تحكيم عقولهم الكاسدة في سنة الرسول عليه الصلاة والسلام، وسوف يكتب في ذلك ما يلزم إن شاء الله، وربما يتيسر أيضاً بحث ذلك في المجمع الفقهي، لمزيد الفائدة ومزيد البيان للناس حتى لا يخدع أحد بهؤلاء الذين يخوضون في الأحاديث بآرائهم، والله المستعان.\nالمقدم: الله المستعان، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8899/الحذر-من-تحكيم-العقول-في-رد-الاحاديث-الصحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34402.mp3","categories":["الحديث وعلومه"]},{"id":10731,"question":"الزميل محمد سعيد الصفار من الرياض بعث برسالة قال فيها: بسم الله الرحمن الرحيم، سماحة الشيخ عبدالعزيز بن عبدالله بن باز حفظه الله، سؤال إلى سماحتكم في هذا البرنامج نور على الدرب، وهو كما يلي: نسمع ونقرأ بين الحين والآخر لبعض المشايخ المعروفين إنكاراً لصحة بعض الأحاديث الواردة في صحيحي البخاري ومسلم ، وبعض كتب الصحاح الأخرى، ويكون إنكارهم لصحتها بعد تمحيصها بعقولهم كما يقولون، أي: أن المعول عليه عندهم في صحة الأحاديث هي عقولهم فقط، ومن ذلك ما قرأناه إنكاراً لأحاديث المهدي والدجال ونزول عيسى ابن مريم، والسؤال يا سماحة الشيخ! هل يجوز لأحد من علماء المسلمين مهما كان قدره أن ينكر صحة بعض الأحاديث الواردة في الصحاح، التي أجمع علماء الأمة على صحتها وتقديم أصحابها، خصوصاً صحيحي البخاري ومسلم بعقله فقط؟ وهل يمكن يا سماحة الشيخ! أن تبحثوا هذا الموضوع في المجمع الفقهي في رابطة العالم الإسلامي لأهميته، حيث أنه مع كثرة العلماء وإنكار كل منهم ما لا يروق له من الأحاديث، قد يتسرب الشك في نفوس عوام المسلمين في صحة أغلب أحاديث السنة المطهرة، ثم إذا رد أحد أصحاب الفضيلة حديثاً في البخاري ومسلم ، فما الذي يجعلنا نصدق بقية الأحاديث، خاصة التي جاءت بسند هذا الحديث المردود، أرجو التفصيل يا سماحة الشيخ! جزاكم الله خيراً؟","title":"الحذر من تحكيم العقول في رد الأحاديث الصحيحة","answer":"الجواب: الأحاديث التي جاءت في الصحيحين بأسانيدهما المعروفة، كلها عند أهل العلم متلقاة بالقبول، ومحكوم بصحتها ولا يجوز لأحد أن يردها، بل يجب قبولها كما قبلها العلماء قبلنا، والذين ردوا أحاديث الدجال أو أحاديث المسيح ابن مريم ، أو أحاديث يأجوج ومأجوج ، قد غلطوا في هذا غلطاً عظيماً وقالوا قولاً باطلاً، لا يجوز اتباعهم عليه ولا تقليدهم فيه، بل يجب عليهم التوبة من ذلك والرجوع إلى ما قاله أهل العلم في إثباتها وصحتها، وهكذا من رد غيرها من الأحاديث الثابتة في الصحيحين لا يلتفت إلى قوله، وليست العقول محكمة في أحاديث الرسول ﷺ، بل الأحاديث تتلقى عن الرسول ﷺ بالأسانيد الصحيحة التي بينها أهل العلم، إذا جاء الحديث من طريق الثقات في الصحيحين أو غيرهما سليماً من العلل وجب أن يقبل، ولا يجوز أن يحكم الرأي في رده من دون حجة شرعية، بل يجب على أهل العلم والإيمان قبول الأحاديث الصحيحة، والاحتجاج بها، والاعتماد عليها، سواء كانت متواترة أو كانت من طريق الآحاد ولا يجوز أبداً أن يقال: هذا من طريق الآحاد، فلا يقبل، كل هذا باطل وخلاف ما أجمع عليه أهل العلم، بل ما صحت به الأخبار عن رسول الله عليه الصلاة والسلام يجب قبوله والأخذ به، حسب ما بينه أهل العلم، ولا يجوز الاعتراض على ذلك بما رآه المتكلمون من تحكيم العقول، وما سلكه بعض المتأخرين في هذا الباب تقليداً لأهل الكلام، وسيراً على منهاجهم في تحكيم عقولهم الكاسدة في سنة الرسول عليه الصلاة والسلام، وسوف يكتب في ذلك ما يلزم إن شاء الله، وربما يتيسر أيضاً بحث ذلك في المجمع الفقهي، لمزيد الفائدة ومزيد البيان للناس حتى لا يخدع أحد بهؤلاء الذين يخوضون في الأحاديث بآرائهم، والله المستعان.\nالمقدم: الله المستعان، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8899/الحذر-من-تحكيم-العقول-في-رد-الاحاديث-الصحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34402.mp3","categories":["الحديث وعلومه"]},{"id":11320,"question":"بعد هذا رسالة بعث بها المستمع سلطان الحارثي، أخونا له أكثر من قضية، في إحدى القضايا التي يسأل عنها يقول: أرجو أن تتفضلوا بإيضاح الفرق بين القرآن الكريم والحديث القدسي؟ وإذا كنت لا أحفظ نص الحديث القدسي فهل يجوز أن أقول معنى ذلكم الحديث كذا وكذا، وهل تجوز صلاة النافلة بالحديث القدسي؟ جزاكم الله خيرًا.","title":"الفروق بين القرآن والحديث القدسي","answer":"الجواب:  القرآن هو كلام الله المعجز الذي جعله الله معجزة للنبي ﷺ وجعله دليلًا على صدق رسالته، وأنه رسول الله حقًا، فالقرآن هو كلام الله، جعله سبحانه معجزة النبي ﷺ ودليلًا على أنه رسول الله حقًا، يقرأ به المؤمن في صلاته وفي غيرها يتعبد بذلك، هو كلام الله حروفه ومعانيه، كلام الله حروفه ومعانيه هو كلام الله تكلم به سبحانه، ونزل به جبرائيل على النبي ﷺ، هذا هو قول أهل السنة والجماعة ، هو كلام الله حقًا ليس كلام غيره. أما الحديث القدسي فهو كلام منسوب إلى الله، نسبه النبي ﷺ إلى الله يقال له: حديث قدسي، يعني حديث عن الله -جل وعلا- وهو أيضًا يعتبر من كلام الله لفظه ومعناه، كما إذا ثبت عن النبي ﷺ قال الله كذا فيعتبر من كلام الله، هذا هو الصحيح لفظه ومعناه، في الحديث يقول الله -جل وعلا-: يا عبادي! إني حرمت الظلم على نفسي وجعلته بينكم محرمًا فلا تظالموا، يا عبادي! كلكم ضال إلا من هديته فاستهدوني أهدكم، هكذا قال النبي ﷺ عن الله . وهكذا ما جاء في معناه من الأحاديث التي ينقل النبي ﷺ، ينقلها النبي ﷺ عن الله يقول: هذا كلام الله هذا يسمى حديثًا قدسيًا، ولكن ليس له حكم في القرآن، ليس بمعجز، ولا يقرأ به في الصلاة، الصلاة يقرأ فيها بالقرآن خاصة، أما الأحاديث القدسية فيقرأها من باب الفائدة لنفسه أو مع إخوانه للفائدة. أما يعني يقرأ في الصلاة بالحديث القدسي في الصلاة لا، ليس حكمه حكم القرآن في هذا، فالقرآن معجز ويقرأ في الصلوات فله حكم آخر، ولكن الحديث القدسي ينسب إلى الله ويقال: إنه كلام الله لفظه ومعناه لكن ليس بمعجز، وليس له حكم القرآن بأن لا يمس الكتاب الذي فيه إلا طاهر وليس هذا حكم القرآن في أن يقرأ به في الصلاة، هذا شيء وهذا شيء، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم، يسأل سماحتكم: هل يجوز أن أروي الحديث القدسي بمعناه؟ الشيخ: إذا تيقنت وعلمت معناه يقينًا وليس عندك شك فاروه بمعناه مثل حديث النبي ﷺ، نعم. المقدم: ما شاء الله، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9496/الفروق-بين-القران-والحديث-القدسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37707.mp3","categories":["الحديث وعلومه"]},{"id":11577,"question":"المستمع (ع. ف. غ) بعث يسأل ويقول: ما هو رأي سماحتكم في الاعتماد على ما صححه الألباني؟","title":"حكم اعتماد تصحيح وتضعيف الألباني للأحاديث","answer":"الجواب:  الشيخ: محمد ناصر الألباني، ناصر الدين الألباني من خيرة الناس، وهو من العلماء المعروفين بالاستقامة، والعقيدة الطيبة، والجد في تصحيح الأحاديث، وبيان حالها، فهو عمدة في هذا الباب، ولكن ليس بمعصوم، قد يقع منه خطأ في تصحيح بعض الأحاديث، أو تضعيفها، ولكن مثل غيره من العلماء كل عالم هكذا له بعض الأخطاء من الأولين والآخرين. فالواجب على طالب العلم أن ينظر فيما صححه وحسنه وضعفه، إذا كان من أهل العلم من أهل الصناعة يعرف الحديث، وينظر في طرقه، وينظر في رجاله، فإن ظهر له صحة ما قاله الشيخ؛ فالحمد لله، وإلا اعتمد ما يظهر له من الأدلة التي سلكها أهل العلم في هذا الباب؛ لأن أهل العلم وضعوا قواعد لتصحيح الأحاديث وتضعيفها، أما غير أهل العلم فمثله عمدة في التصحيح والتضعيف؛ لأنه من أهل العلم ومن أهل هذا الشأن، وقد درس هذا من مدة طويلة، وسنوات كثيرة، نسأل الله لنا وله التوفيق، وحسن العاقبة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9760/حكم-اعتماد-تصحيح-وتضعيف-الالباني-للاحاديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29802.mp3","categories":["الحديث وعلومه"]},{"id":12316,"question":"نقف قليلًا -لو تكرمتم سماحة الشيخ- عند العمل بالأحاديث الضعيفة، هل يشرع ذلك؟","title":"حكم العمل بالحديث الضعيف","answer":"الجواب: إذا وافقت الأحاديث الصحيحة في المعنى، كأحاديث الأذكار، والاستغفار والتوبة، من غير اعتقاد ما علق عليه في الحديث الضعيف، نعم. المقدم: الله المستعان إذًا: إذا لم يكن لها سند صحيح؛ فلا يعمل بها؟ الشيخ: والمعنى صحيح، إذا كان المعنى صحيحًا؛ فلا بأس. المقدم: إذا كان المعنى صحيحًا. الشيخ: يعمل به، ولا بأس؛ فلا يضر، لكن من غير اعتقاد ما جاء في الحديث، أنه يفعله كذا، وأنه يحصل له كذا، ويحصل له كذا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10525/حكم-العمل-بالحديث-الضعيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39812.mp3","categories":["الحديث وعلومه"]},{"id":12320,"question":"نقف قليلًا -لو تكرمتم سماحة الشيخ- عند العمل بالأحاديث الضعيفة، هل يشرع ذلك؟","title":"حكم العمل بالحديث الضعيف","answer":"الجواب: إذا وافقت الأحاديث الصحيحة في المعنى، كأحاديث الأذكار، والاستغفار والتوبة، من غير اعتقاد ما علق عليه في الحديث الضعيف، نعم. المقدم: الله المستعان إذًا: إذا لم يكن لها سند صحيح؛ فلا يعمل بها؟ الشيخ: والمعنى صحيح، إذا كان المعنى صحيحًا؛ فلا بأس. المقدم: إذا كان المعنى صحيحًا. الشيخ: يعمل به، ولا بأس؛ فلا يضر، لكن من غير اعتقاد ما جاء في الحديث، أنه يفعله كذا، وأنه يحصل له كذا، ويحصل له كذا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10525/حكم-العمل-بالحديث-الضعيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39812.mp3","categories":["الحديث وعلومه"]},{"id":13667,"question":"كثر في زماننا هذا -سماحة الشيخ عبدالعزيز- الأحاديث الموضوعة، فهل من معالجة لمثل هذا الموضوع سماحة الشيخ عبدالعزيز؟","title":"التحذير من الأحاديث الموضوعة","answer":"الجواب: الأحاديث الموضوعة كثيرة من قديم الزمان، وقد صنف فيها العلماء من عهد الصحابة إلى يومنا هذا، والوضاعون كثيرون وضعوا على النبي ﷺ وعلى غيره، ولكن كلما قل العلم، وقل العلماء؛ انتشرت هذه الأكاذيب، وهذه التراهات، وهذه الجهالات، وكلما كثر العلماء في البلد قضي عليها، وما ذاك إلا لأن أعداء الإسلام كثيرون، والجهلة من طلبة العلم، ومن العباد كثيرون، فيحسبون أن الأحاديث التي يرويها بعض الكذبة صحيحة، فينشرونها إما في فضل الصلاة، أو فضل الصوم، أو فضل الصدقة، أو في غير ذلك، وبعض الناس أعداء الإسلام يكذبون وينشرون عداوة للإسلام، وتشويهًا للإسلام. فالواجب على المسلم أن يحذر تصديقهم وأن لا يقبل من الأحاديث إلا ما شهد به أهل العلم، وبينه له أهل العلم، إذا كان لا يعلم يسأل أهل العلم، أما إذا كان عنده علم؛ فالحمد لله، قد بين أهل العلم ما يعرف بالحديث الضعيف، والموضوع، والصحيح إذا قرأ كلام أهل العلم؛ عرف ذلك. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12011/التحذير-من-الاحاديث-الموضوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52910.mp3","categories":["الحديث وعلومه"]},{"id":13776,"question":"أخونا السائل إبراهيم أبو حامد الحقيقة متواصل مع البرنامج أرسل بهذه الأسئلة يقول: ما الفرق بين القرآن والحديث القدسي، وبين الحديث القدسي والحديث النبوي؟","title":"الفرق بين القرآن والحديث القدسي والنبوي","answer":"الجواب: القرآن هو كلام الله، منزل غير مخلوق، منه بدأ وإليه يعود، وله أحكام، يقرأ في الصلاة، ولا يمس المصحف إلا طاهر، وفرض أن تقرأ الفاتحة في الصلاة، ويشرع قراءته في الصلاة. وأما الحديث القدسي فهو كلام الله الذي ينقله النبي ﷺ هذا له حكم أنه كلام الله، لكن ما يكون له حكم القرآن في أن يقرأ في الصلاة، أو يمنع من كان على غير وضوء أن يلمس الأوراق التي فيه الأحاديث القدسية، فهذا المنع من مس القرآن إلا من كان على طهارة يختص بالقرآن. أما الأحاديث القدسية فلا يمنع من كان على غير وضوء أن يمسها، أو يقرأها، لا الجنب، ولا غيره، وكذلك لا تقرأ في الصلاة ليس لها حكم القرآن مثل حديث: يقول الله -جل وعلا-: يا عبادي! إني حرمت الظلم على نفسي، وجعلته بينكم محرمًا؛ فلا تظالموا، يا عبادي! كلكم ضال إلا من هديته، فاستهدوني؛ أهدكم، يا عبادي! كلكم عارٍ إلا من كسوته، فاستكسوني؛ أكسكم، يا عبادي كلكم جائع إلا من أطعمته، فاستطعموني؛ أطعمكم، يا عبادي! إنكم لن تبلغوا ضري فتضروني، ولن تبلغوا نفعي فتنفعوني.. إلى غير هذا.  فهذه أحاديث قدسية هذا من كلام الله، ليس من كلام الرسول ﷺ بل هو كلام الله، لكنه ليس مثل القرآن، بل يجوز أن يلمس الصحيفة التي فيها هذا الحديث المحدث والجنب، وليس له أن يقرأها في الصلاة. وأما كلام النبي ﷺ فهو ما صدر منه قوله كلامه مثل قوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى هذا كلام النبي ﷺ .. ومثل قوله ﷺ: لا تقبل صلاة بغير طهور، ولا صدقة من غلول ومثل قوله ﷺ: بني الإسلام على خمس: شهادة أن لا إله إلا الله، وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت. ومثل قوله ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، وأن محمدًا رسول الله، ويقيموا الصلاة، ويؤتوا الزكاة، فإذا فعلوا ذلك؛ عصموا مني دماءهم، وأموالهم إلا بحق الإسلام، وحسابهم على الله والأحاديث في هذا كثيرة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12144/الفرق-بين-القران-والحديث-القدسي-والنبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53602.mp3","categories":["الحديث وعلومه","القرآن وعلومه"]},{"id":14776,"question":"سماحة الشيخ، تشيرون إلى أسباب ورود الحديث، يبدو لي أن هذا علمٌ مستقلٌ بذاته، هل تتفضلون بإلقاء الضوء عليه؟","title":"من فوائد معرفة أسباب ورود الأحاديث","answer":"الجواب: نعم، نعم، بيان أسباب الحديث مما يعين على فهمه، وجاء بينه وبين غيره من الأحاديث التي قد يبدو لبعض الناس أن هناك تخالفًا، وتعارضًا، فإذا سمع القارئ أو اطلع القارئ على سبب الحديث، زال عنه الإشكال، واتضح له اتفاق السنة، وائتلافها، وأن بعضها يصدق بعضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13276/من-فواىد-معرفة-اسباب-ورود-الاحاديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64102.mp3","categories":["الحديث وعلومه"]},{"id":14779,"question":"سماحة الشيخ، تشيرون إلى أسباب ورود الحديث، يبدو لي أن هذا علمٌ مستقلٌ بذاته، هل تتفضلون بإلقاء الضوء عليه؟","title":"من فوائد معرفة أسباب ورود الأحاديث","answer":"الجواب: نعم، نعم، بيان أسباب الحديث مما يعين على فهمه، وجاء بينه وبين غيره من الأحاديث التي قد يبدو لبعض الناس أن هناك تخالفًا، وتعارضًا، فإذا سمع القارئ أو اطلع القارئ على سبب الحديث، زال عنه الإشكال، واتضح له اتفاق السنة، وائتلافها، وأن بعضها يصدق بعضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13276/من-فواىد-معرفة-اسباب-ورود-الاحاديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64102.mp3","categories":["الحديث وعلومه"]},{"id":14974,"question":"هذا سائل للبرنامج أرسل الحقيقة بمجموعة من الأسئلة، يبدأ هذه الصفحة بالسؤال الأول، ويقول: هل يجوز للعالم أن يفتي ويستدل بالأحاديث الضعيفة؟","title":"حكم الاستدلال بالأحاديث الضعيفة","answer":"الجواب: نعم، يجوز للعالم أن يفتي بالأدلة الشرعية، وإذا استشهد بالأحاديث الضعيفة التي تعددت طرقها، وصارت من قبيل الحسن لغيره فلا بأس، لكن عليه أن يجتهد، ويتحرى الحق بالدليل من القرآن والسنة، وإذا استشهد بعض الأحيان ببعض الأحاديث الضعيفة التي ليست موضوعة، بل ضعيفة غير موضوعة فلا بأس، يقول الحافظ العراقي -رحمه الله- في ألفيته: وسهلوا -يعني: أهل العلم، أهل الحديث-:","link":"https://binbaz.org.sa/fatwas/13474/حكم-الاستدلال-بالاحاديث-الضعيفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56217.mp3","categories":["الحديث وعلومه","العالم والمتعلم"]},{"id":17024,"question":"تقول: لقد اختلط على الناس أمر الأحاديث التي يقرؤونها، أو يسمعونها هل هي صحيحة، أم ضعيفة؟ ويقال: إن كتاب صحيح الجامع الصغير وزيادته للألباني يوضح الأحاديث الضعيفة من الصحيحة، ما هو توجيهكم؟","title":"توجيه حول كتب الألباني وتصحيحه وتضعيفه للأحاديث","answer":"الجواب: نعم كتب الألباني جيدة، ومفيدة، وفقه الله، وهو الشيخ محمد ناصر الألباني، هو رجل متفرغ لهذا الأمر، وقد اعتنى به كثيرًا في تحري الأحاديث الصحيحة، والتنبيه عليها، والأحاديث الضعيفة، فكتبه مفيدة، ونافعة، ولكن ليس معصومًا، فقد يقع بعض الخطأ في بعض الأحاديث، وقد يعتقدها صحيحة وهي ضعيفة، وقد يعتقدها ضعيفة وهي صحيحة، لكن هذا قليل، وطالب العلم يجتهد في معرفة الصحيح، والسقيم بالطرق التي أوضحها العلماء. والاستفادة من كتب الشيخ ناصر الدين الألباني طيبة، ينبغي للمؤمن، والمؤمنة أن يستفيد منها ومن أمثالها، مثل: صحيح البخاري .. صحيح مسلم .. رياض الصالحين، كلام العلماء على الأحاديث الضعيفة في كتبهم المؤلفة في هذا الباب مثل: شرح الجامع الصغير.. كشف الخفاء، وغير ذلك من الكتب التي ألفت في هذا الباب، حتى يستفيد المؤمن من كلام العلماء. نعم. المقدم: جزاكم الله خيرًا، ما رأيكم سماحة الشيخ فيما ضعفه الشيخ الألباني ؟ الشيخ: مثل ما تقدم، الغالب على ما ضعفه وصححه الصحة؛ لأنه معتني -وفقه الله- وله خبرة بهذا الباب، فالغالب على ما صححه وضعفه أن كلامه فيه جيد، ومستقيم. نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15809/توجيه-حول-كتب-الالباني-وتصحيحه-وتضعيفه-للاحاديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83004.mp3","categories":["الحديث وعلومه","العالم والمتعلم"]},{"id":18108,"question":"يسأل أخونا ويقول: كثيرًا ما أسمع عن الأحاديث القدسية، بودي أن تنوروني بعض الشيء بخصوصها، جزاكم الله خيرًا.","title":"تعريف الحديث القدسي","answer":"الجواب: الأحاديث القدسية هي التي يرويها الرسول ﷺ عن ربه جل وعلا يقال لها أحاديث قدسية، يعني: مقدسة منزهة؛ لأنها من كلام الرب ، وهي مثل القرآن كلام الله جل وعلا لكن القرآن معجزة مستمرة مأمور الناس أن يتطهروا عند لمس المصحف، والقرآن معجز وهو كلام الله . وأما الأحاديث القدسية فهي كلام الرب  لكن ليس لها حكم القرآن في وجوب التطهر عند مسها، بل لها لون آخر فهي من كلام الرب لكنها غير القرآن اللي هو المعجز المستمر للنبي عليه الصلاة والسلام، هو معجزة من دلائل النبوة، وكلام الرب  في الأحاديث القدسية كلام الرب منزل غير مخلوق لكنه ليس من جنس القرآن، بل القرآن معجزة مستمرة دالة على صدق الرسول ﷺ، وله أحكام غير أحكام الأحاديث القدسية. والأحاديث القدسية مثلما ثبت في الصحيح عن أبي ذر  عن النبي عليه الصلاة والسلام أنه قال: يقول الله : يا عبادي! إني حرمت الظلم على نفسي وجعلته بينكم محرمًا فلا تظالموا، يا عبادي! كلكم ضال إلا من هديته فاستهدوني أهدكم، يا عبادي! كلكم عار إلا من كسوته فاستكسوني أكسكم، يا عبادي! كلكم جائع إلا من أطعمته فاستطعموني أطعمكم، يا عبادي! إنكم لن تبلغوا ضري فتضروني ولن تبلغوا نفعي فتنفعوني. يا عبادي! إنكم تخطئون بالليل والنهار وأنا أغفر الذنوب جميعًا فاستغفروني أغفر لكم، يا عبادي! لو أن أولكم وآخركم وإنسكم وجنكم كانوا على أتقى قلب رجل واحد منكم ما زاد ذلك في ملكي شيئًا، يا عبادي! لو أن أولكم وآخركم وإنسكم وجنكم كانوا على أفجر قلب رجل واحد منكم ما نقص ذلك من ملكي شيئًا، يا عبادي! لو أن أولكم وآخركم وإنسكم وجنكم قاموا في صعيد واحد فسألوني فأعطيت كل إنسان مسألته ما نقص ذلك مما عندي شيئًا إلا كما ينقص المخيط إذا أدخل البحر، يا عبادي! إنما هي أعمالكم أحصيها لكم ثم أوفيكم إياها فمن وجد خيرًا، فليحمد الله ومن وجد غير ذلك فلا يلومن إلا نفسه خرجه الإمام مسلم في صحيحه. هذا الحديث العظيم يسمى حديثًا قدسيًا، وهو دال على فوائد عظيمة من كلام الرب  كما سمعتم أيها المستمعون. وهو حديث قدسي عظيم دال على تحريم الظلم ودال على افتقار العباد إلى ربهم وأنهم فقراء إليه، فهو المنعم عليهم الذي يهدي من شاء ويطعم من يشاء، ويغني من يشاء ويفقر من يشاء، فهو سبحانه الذي يغفر الذنوب ويستر العيوب جل وعلا، وهو الغني عن عباده لا يستطيعوا أن يضروه ولا أن ينفعوه فهو غني عنهم ، وهو جل وعلا لا تنقصه معاصيهم ولا تنفعه طاعاتهم، بل طاعاتهم لهم تنفعهم ومعاصيهم تضرهم. أما هو سبحانه فلا تنفعه طاعاتهم ولا تزيد في ملكه شيئًا، كما أن معاصي الناس لا تنقصه ولا تضره سبحانه وتعالى شيئاً، ثم بين سبحانه أن العباد لو اجتمعوا في صعيد واحد وسألوا ربهم كل ما يريدون من المسائل والحاجات ما نقص ذلك مما عنده شيئًا ؛ لأن خزائنه ملأى لا يغيضها شيء . ثم بين سبحانه أن الحاصل والخلاصة أنها أعمالهم يحصيها الرب جل وعلا لهم ثم يوفيهم إياها، يعني أجورهم إن كانت طيبة أو عقابهم إن كانت سيئة؛ ولهذا قال: فمن وجد خيرًا فليحمد الله الذي وفقه لطاعته وهداه وأعانه، ومن وجد غير ذلك من وجد أعماله خبيثة توجب النار فلا يلومن إلا نفسه لأنه فرط وأضاع وتساهل وتابع الهوى والشيطان، ولا حول ولا قوة إلا بالله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17143/تعريف-الحديث-القدسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_904/nour_90408.mp3","categories":["القرآن وعلومه","الحديث وعلومه"]},{"id":18766,"question":"سماحة الشيخ، كثرت الأحاديث الموضوعة! فما السبيل إلى العلاج في تدارك هذه الأحاديث الموضوعة؟","title":"السبيل إلى علاج كثرة الأحاديث الموضوعة","answer":"الجواب: تداركها العلماء، ألفوا فيها مؤلفات، والحمد لله وضحوها، فيها مؤلفات كثيرة وضحت الموضوعة والضعيفة: الموضوعات لابن الجوزي، والجامع الصغير للسيوطي، وشرح المناوي كشف الخفاء للعجلوني، وكتب أخرى وضحوا فيها، نصب الراية للهيثمي وغير ذلك، نعم، كتب كثيرة ألفت في هذا الباب، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17890/السبيل-الى-علاج-كثرة-الاحاديث-الموضوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79016.mp3","categories":["الحديث وعلومه"]},{"id":19184,"question":"يسأل أخونا ويقول: ما هي كتب السنة التي ترون أنها مناسبة وتنصحوننا باقتنائها؟","title":"كتب السنة التي ينصح باقتنائها","answer":"الجواب: كتب السنة كثيرة والحمد لله، منها الكتب الستة، الصحيحين، وأبو داود ، والترمذي، والنسائي، وابن ماجة، وموطأ مالك رحمه الله، ومسند أحمد، هذه كتب الحديث المعروفة، وهناك كتب أخرى معروفة. ومن كتب السنة ما ألفه أهل العلم المعروفون مثل: ما ألفه الشافعي رحمه الله، كتاب الأم للشافعي، والموطأ لـمالك رحمه الله، ومنها ما ألفه الفقهاء بعد ذلك في أحكام الشرع المطهر، ومن أحسن ما ألف في ذلك مؤلفات شيخ الإسلام ابن تيمية رحمه الله، و ابن القيم رحمه الله، فإنها كتب مفيدة تعتني بالدليل، وترجح الراجح في مسائل الخلاف، فهي كتب عظيمة. وهكذا كتب أئمة الدعوة الذين نشطوا في الدعوة ونشروها في أرض الجزيرة في القرن الثاني عشر، في النصف الثاني من القرن الثاني عشر وما بعده، وهم الشيخ: محمد بن عبد الوهاب رحمه الله، وأحفاده وأولاده وأنصاره من دعاة السنة؛ فإن كتبهم مفيدة وعظيمة، مثل: الدرر السنية في الفتاوى النجدية، ومثل: فتح المجيد شرح كتاب التوحيد، ومثل كتاب التوحيد، كشف الشبهات، مثل آداب المشي إلى الصلاة، وهكذا في العقيدة: العقيدة الواسطية لشيخ الإسلام ابن تيمية، والتدمرية له أيضًا، والحموية كل هذه كتب عظيمة ومفيدة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18362/كتب-السنة-التي-ينصح-باقتناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93211.mp3","categories":["الحديث وعلومه"]},{"id":19712,"question":"حديث الجساسة؟","title":"ما صحة حديث الجساسة ونقد الصحيحين؟","answer":"صحيح في \"مسلم\"، المقصود أن \"الصحيحين\" تلقَّاهما أهلُ العلم والإيمان بالقبول، وهما كتابان عظيمان، تلقَّاهما الأئمةُ بالقبول، يعني: ما فيهما من الأحاديث المسندة الصحيحة والمعلَّقة في الصحيح فقد تقبَّلها الأئمةُ، لكن وجود بعض الألفاظ وبعض الأغلاط وبعض الوهم من بعض الرواة، هذا ما يمنع.","link":"https://binbaz.org.sa/fatwas/27093/ما-صحة-حديث-الجساسة-ونقد-الصحيحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D8%AD%D8%AF%D9%8A%D8%AB%20%D8%A7%D9%84%D8%AC%D8%B3%D8%A7%D8%B3%D8%A9%20%D9%88%D8%A7%D9%84%D8%B1%D8%AF%20%D8%B9%D9%84%D9%89%20%D9%86%D9%82%D8%AF%20%D8%A7%D9%84%D8%B5%D8%AD%D9%8A%D8%AD%D9%8A%D9%86.mp3","categories":["الحديث وعلومه"]}]
